      --radius-sm: 0.75rem;
      color-scheme: light;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font: 400 1rem/1.6 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--color-text);
      background:
        radial-gradient(circle at top left, #fdfaf6 0, transparent 36%),
        linear-gradient(180deg, #f8f5f0 0%, var(--color-bg) 100%);
    }

    img {
      max-width: 100%;
      display: block;
    }

    a {
      color: var(--color-link);
      text-decoration-thickness: 0.12em;
      text-underline-offset: 0.18em;
    }

    a:hover {
      text-decoration-thickness: 0.16em;
    }

    :focus-visible {
      outline: 0.18rem solid var(--color-focus);
      outline-offset: 0.2rem;
    }

    .skip-link {
      position: absolute;
      inset-inline-start: 1rem;
      inset-block-start: 1rem;
      z-index: 20;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--color-text);
      color: #fff;
      transform: translateY(-160%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus,
    .skip-link:active {
      transform: translateY(0);
    }

    .page-shell {
      width: min(72rem, calc(100% - 2rem));
      margin: 0 auto;
    }

    .site-header {
      padding: 1rem 0 0;
    }

    .masthead {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.25rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.72);
      backdrop-filter: blur(14px);
      box-shadow: var(--shadow);
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      color: var(--color-text);
      text-decoration: none;
      font-weight: 750;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      display: inline-grid;
      place-items: center;
      width: 2.25rem;
      height: 2.25rem;
      border-radius: 999px;
      background: linear-gradient(135deg, #1f6f8b, #d98c52);
      color: #fff;
      font-size: 1rem;
      flex: 0 0 auto;
    }

    .top-nav {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 0.9rem 1.2rem;
    }

    .top-nav a {
      font-weight: 600;
      color: var(--color-text);
      text-decoration: none;
    }

    .top-nav a:hover,
    .top-nav a:focus-visible {
      color: var(--color-link);
    }

    main {
      display: grid;
      gap: 3rem;
      padding: 1.5rem 0 4rem;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.25fr) minmax(18rem, 0.75fr);
      gap: 1.5rem;
      align-items: stretch;
    }

    .hero-copy,
    .hero-panel,
    .section-card,
    .product-card,
    .deal-card,
    .editorial-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.5rem, 4vw, 3rem);
      display: grid;
      align-content: start;
      gap: 1.2rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      padding: 0.4rem 0.75rem;
      border-radius: 999px;
      background: var(--color-surface-strong);
      color: var(--color-muted-text);
      font-size: 0.92rem;
      font-weight: 650;
    }

    h1,
    h2,
    h3,
    p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2.4rem, 6vw, 4.8rem);
      line-height: 0.98;
      letter-spacing: -0.05em;
      max-width: 10ch;
    }

    .hero-copy p {
      max-width: 40rem;
      font-size: 1.06rem;
      color: var(--color-muted-text);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
      margin-top: 0.35rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.6rem;
      min-height: 2.9rem;
      padding: 0.75rem 1.15rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font: inherit;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
      transition: transform 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-primary {
      background: var(--color-text);
      color: #fff;
    }

    .button-secondary {
      background: var(--color-surface);
      color: var(--color-text);
      border-color: var(--color-border);
    }

    .hero-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      margin-top: 0.5rem;
    }

    .stat {
      padding-top: 1rem;
      border-top: 1px solid var(--color-border);
    }

    .stat strong {
      display: block;
      font-size: 1.25rem;
      line-height: 1.2;
    }

    .hero-panel {
      display: grid;
      gap: 1rem;
      padding: 1rem;
      background: linear-gradient(180deg, #fffefc 0%, #f4ece2 100%);
    }

    .hero-image {
      aspect-ratio: 4 / 5;
      border-radius: calc(var(--radius-lg) - 0.25rem);
      overflow: hidden;
      border: 1px solid rgba(23, 20, 18, 0.08);
      background: #e8dfd4;
    }

    .hero-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-panel-content {
      display: grid;
      gap: 0.75rem;
    }

    .price-tag {
      display: inline-flex;
      align-items: center;
      width: fit-content;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: #fff;
      border: 1px solid var(--color-border);
      font-weight: 700;
    }

    .section-card {
      padding: clamp(1.2rem, 3vw, 1.6rem);
    }

    .section-heading {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1.2rem;
    }

    .section-heading p {
      max-width: 42rem;
      color: var(--color-muted-text);
    }

    .grid-products,
    .grid-deals,
    .grid-editorial {
      display: grid;
      gap: 1rem;
    }

    .grid-products {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .grid-deals {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .grid-editorial {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .product-card,
    .deal-card,
    .editorial-card {
      overflow: hidden;
      min-width: 0;
    }

    .product-media,
    .deal-media {
      aspect-ratio: 4 / 3;
      background: var(--color-surface-strong);
      border-bottom: 1px solid var(--color-border);
    }

    .product-media img,
    .deal-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .product-body,
    .deal-body,
    .editorial-body {
      display: grid;
      gap: 0.75rem;
      padding: 1rem;
    }

    .meta-row {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      align-items: start;
    }

    .product-card h3,
    .deal-card h3,
    .editorial-card h3 {
      font-size: 1.08rem;
      line-height: 1.3;
    }

    .product-card p,
    .deal-card p,
    .editorial-card p,
    .fine-print {
      color: var(--color-muted-text);
    }

    .tag {
      display: inline-flex;
      align-items: center;
      width: fit-content;
      padding: 0.25rem 0.55rem;
      border-radius: 999px;
      background: #edf4f8;
      color: #20536f;
      font-size: 0.84rem;
      font-weight: 650;
    }

    .product-price {
      font-weight: 800;
      font-size: 1.12rem;
    }

    .deal-card {
      border-color: #e4cab4;
      background: linear-gradient(180deg, #fff7ef 0%, #fff 100%);
    }

    .deal-kicker {
      color: var(--color-danger);
      font-weight: 800;
      font-size: 0.88rem;
      letter-spacing: 0.02em;
    }

    .editorial-card .button {
      width: fit-content;
      padding-inline: 0;
      min-height: auto;
      background: transparent;
      color: var(--color-link);
      box-shadow: none;
      border-radius: 0;
      font-weight: 700;
    }

    .newsletter {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 1rem;
      align-items: center;
    }

    .newsletter form {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      justify-content: end;
    }

    .newsletter input {
      min-width: min(100%, 18rem);
      flex: 1 1 18rem;
      min-height: 2.9rem;
      padding: 0.75rem 1rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      font: inherit;
      color: var(--color-text);
      background: #fff;
    }

    .newsletter input::placeholder {
      color: #7b746e;
    }

    .newsletter-status {
      min-height: 1.5rem;
      color: var(--color-success);
      font-weight: 650;
    }

    .site-footer {
      padding: 0 0 3rem;
    }

    .footer-card {
      display: grid;
      gap: 1rem;
      padding: 1.2rem 1.4rem;
      border-radius: var(--radius-lg);
      border: 1px solid var(--color-border);
      background: rgba(255, 255, 255, 0.84);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .footer-grid h2 {
      font-size: 1rem;
      margin-bottom: 0.5rem;
    }

    .footer-grid ul {
      list-style: none;
      padding: 0;
      margin: 0;
      display: grid;
      gap: 0.4rem;
    }

    .footer-grid a {
      color: var(--color-text);
      text-decoration: none;
    }

    .footer-grid a:hover,
    .footer-grid a:focus-visible {
      color: var(--color-link);
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      color: var(--color-muted-text);
      font-size: 0.94rem;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      clip-path: inset(50%);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 56rem) {
      .hero,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .hero-stats,
      .grid-products,
      .grid-deals,
      .grid-editorial,
      .footer-grid {
        grid-template-columns: 1fr;
      }

      .masthead,
      .section-heading,
      .footer-bottom {
        align-items: start;
      }
    }

    @media (max-width: 40rem) {
      .page-shell {
        width: min(100% - 1rem, 72rem);
      }

      .masthead {
        border-radius: 1.25rem;
        padding-inline: 1rem;
      }

      .top-nav {
        justify-content: flex-start;
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-surface-strong: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-link: LinkText;
        --color-border: ButtonBorder;
        --color-focus: Highlight;
      }

      .masthead,
      .hero-copy,
      .hero-panel,
      .section-card,
      .product-card,
      .deal-card,
      .editorial-card,
      .footer-card,
      .newsletter input,
      .button,
      .tag,
      .price-tag {
        forced-color-adjust: auto;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .button-primary {
        background: ButtonFace;
        color: ButtonText;
      }

      .button-secondary,
      .newsletter input {
        background: Canvas;
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div id="app"></div>

  <script>
    const products = [
      {
        name: "Everyday wool coat",
        category: "Outerwear",
        price: "$248",
        note: "Warm without the bulk, tailored for daily wear.",
        image: svgDataUri("Camel wool coat on a clean studio backdrop"),
        alt: "Camel wool coat styled on a neutral studio backdrop"
      },
      {
        name: "Soft leather tote",
        category: "Accessories",
        price: "$138",
        note: "Roomy interior, structured shape, and hidden pockets.",
        image: svgDataUri("Leather tote with folded strap details"),
        alt: "Soft tan leather tote with structured handles"
      },
      {
        name: "Cloud knit sneaker",
        category: "Footwear",
        price: "$112",
        note: "Breathable, cushioned, and easy to wear all day.",
        image: svgDataUri("Minimal sneaker with layered sole"),
        alt: "Minimal white sneaker with layered sole and knit upper"
      }
    ];

    const deals = [
      {
        title: "Winter layers event",
        kicker: "Up to 40% off",
        description: "Refresh cold-weather staples with knitwear, coats, and boots made for layering."
      },
      {
        title: "Home reset favorites",
        kicker: "Bundle and save",
        description: "Add texture and warmth with storage, tableware, and soft goods selected for the season."
      },
      {
        title: "Gift edit under $75",
        kicker: "New markdowns",
        description: "Thoughtful accessories, desk essentials, and small luxuries that still feel elevated."
      }
    ];

    const editorials = [
      {
        title: "A calmer capsule for the city commute",
        category: "Style guide",
        description: "Three neutral pieces that mix easily and keep a polished silhouette from morning to evening."
      },
      {
        title: "How to build a welcoming entryway",
        category: "Home notes",
        description: "Storage, lighting, and tactile finishes that make the first five feet feel intentional."
      },
      {
        title: "The weekend packing list we trust",
        category: "Travel journal",
        description: "Compact essentials that balance comfort, durability, and a little bit of color."
      }
    ];

    function svgDataUri(label) {
      const svg = `
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 600" role="img" aria-label="${label}">
          <defs>
            <linearGradient id="bg" x1="0" x2="1" y1="0" y2="1">
              <stop offset="0%" stop-color="#f7efe6" />
              <stop offset="100%" stop-color="#d7c1aa" />
            </linearGradient>
            <linearGradient id="accent" x1="0" x2="1" y1="0" y2="1">
              <stop offset="0%" stop-color="#2f6677" />
              <stop offset="100%" stop-color="#d88d53" />
            </linearGradient>
          </defs>
          <rect width="800" height="600" fill="url(#bg)" />
          <circle cx="560" cy="160" r="110" fill="#fff8ef" />
          <circle cx="220" cy="460" r="150" fill="#efe5d8" />
          <path d="M260 160c70-36 156-34 230 8 27 15 44 42 44 73v169c0 38-30 69-68 69H332c-38 0-68-31-68-69V234c0-28 13-53 36-69z" fill="#805944" opacity="0.92"/>
          <path d="M310 145c0-55 41-94 90-94s90 39 90 94" fill="none" stroke="url(#accent)" stroke-width="24" stroke-linecap="round"/>
          <path d="M274 265h252" stroke="#f2ded0" stroke-width="18" stroke-linecap="round"/>
          <rect x="332" y="326" width="136" height="68" rx="30" fill="#f8f2ea"/>
          <path d="M145 495l90-44 76 54-88 45z" fill="#1e404a" opacity="0.82"/>
          <path d="M555 470l112-50 71 30-112 54z" fill="#7b5138" opacity="0.82"/>
        </svg>`;
      return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
    }

    function productCard(item) {
      return `
        <article class="product-card">
          <div class="product-media">
            <img src="${item.image}" alt="${item.alt}" />
          </div>
          <div class="product-body">
            <div class="meta-row">
              <div>
                <span class="tag">${item.category}</span>
                <h3>${item.name}</h3>
              </div>
              <span class="product-price">${item.price}</span>
            </div>
            <p>${item.note}</p>
            <a class="button button-secondary" href="#featured-products">Shop now</a>
          </div>
        </article>
      `;
    }

    function dealCard(item) {
      return `
        <article class="deal-card">
          <div class="deal-body">
            <span class="deal-kicker">${item.kicker}</span>
            <h3>${item.title}</h3>
            <p>${item.description}</p>
            <a class="button button-secondary" href="#deals">Browse deal</a>
          </div>
        </article>
      `;
    }

    function editorialCard(item) {
      return `
        <article class="editorial-card">
          <div class="editorial-body">
            <span class="tag">${item.category}</span>
            <h3>${item.title}</h3>
            <p>${item.description}</p>
            <a class="button" href="#editorial">Read story</a>
          </div>
        </article>
      `;
    }

    document.getElementById("app").innerHTML = `
      <header class="site-header">
        <div class="page-shell masthead">
          <a class="brand" href="#" aria-label="Northstar Retail home">
            <span class="brand-mark" aria-hidden="true">N</span>
            <span>Northstar Retail</span>
          </a>
          <nav class="top-nav" aria-label="Primary">
            <a href="#featured-products">Featured</a>
            <a href="#deals">Deals</a>
            <a href="#editorial">Editorial</a>
            <a href="#newsletter">Newsletter</a>
          </nav>
        </div>
      </header>

      <main id="maincontent" tabindex="-1">
        <section class="page-shell hero" aria-labelledby="hero-title">
          <div class="hero-copy">
            <span class="eyebrow">New season arrivals</span>
            <h1 id="hero-title">Modern essentials with a warmer point of view.</h1>
            <p>Discover refined everyday pieces, limited-time deals, and editorial picks that make shopping feel easier and more considered.</p>
            <div class="hero-actions">
              <a class="button button-primary" href="#featured-products">Shop featured</a>
              <a class="button button-secondary" href="#deals">See deals</a>
            </div>
            <div class="hero-stats" aria-label="Brand highlights">
              <div class="stat">
                <strong>24-hour shipping</strong>
                <span class="fine-print">On eligible orders in major metros.</span>
              </div>
              <div class="stat">
                <strong>4.8/5 rating</strong>
                <span class="fine-print">From customers who return for staples.</span>
              </div>
              <div class="stat">
                <strong>Easy returns</strong>
                <span class="fine-print">Free returns within 30 days.</span>
              </div>
            </div>
          </div>

          <aside class="hero-panel" aria-label="Spotlight product">
            <div class="hero-image">
              <img src="${products[0].image}" alt="${products[0].alt}" />
            </div>
            <div class="hero-panel-content">
              <span class="price-tag">Best seller • ${products[0].price}</span>
              <h2>${products[0].name}</h2>
              <p>${products[0].note}</p>
              <a class="button button-primary" href="#featured-products">View collection</a>
            </div>
          </aside>
        </section>

        <section class="page-shell section-card" id="featured-products" aria-labelledby="featured-heading">
          <div class="section-heading">
            <div>
              <span class="eyebrow">Featured products</span>
              <h2 id="featured-heading">Our favorite picks, styled for everyday use.</h2>
            </div>
            <p>Well-made essentials with neutral palettes, tactile materials, and easy-to-style silhouettes.</p>
          </div>
          <div class="grid-products">
            ${products.map(productCard).join("")}
          </div>
        </section>

        <section class="page-shell section-card" id="deals" aria-labelledby="deals-heading">
          <div class="section-heading">
            <div>
              <span class="eyebrow">Deals</span>
              <h2 id="deals-heading">Limited-time offers worth checking before you browse elsewhere.</h2>
            </div>
            <p>From seasonal markdowns to bundle savings, these edits are curated to feel useful rather than noisy.</p>
          </div>
          <div class="grid-deals">
            ${deals.map(dealCard).join("")}
          </div>
        </section>

        <section class="page-shell section-card" id="editorial" aria-labelledby="editorial-heading">
          <div class="section-heading">
            <div>
              <span class="eyebrow">Editorial content</span>
              <h2 id="editorial-heading">Ideas, stories, and styling notes from the brand team.</h2>
            </div>
            <p>Short reads with practical advice so the page feels like a destination, not just a catalog.</p>
          </div>
          <div class="grid-editorial">
            ${editorials.map(editorialCard).join("")}
          </div>
        </section>

        <section class="page-shell section-card" id="newsletter" aria-labelledby="newsletter-heading">
          <div class="newsletter">
            <div>
              <span class="eyebrow">Stay in the loop</span>
              <h2 id="newsletter-heading">Get new arrivals and sale alerts in your inbox.</h2>
              <p class="fine-print">One concise email a week with products, styling ideas, and first-look offers.</p>
            </div>
            <form id="newsletter-form">
              <label class="visually-hidden" for="email">Email address</label>
              <input id="email" type="email" name="email" placeholder="Email address" autocomplete="email" />
              <button class="button button-primary" type="submit">Sign up</button>
              <p class="newsletter-status" id="newsletter-status" aria-live="polite"></p>
            </form>
          </div>
        </section>
      </main>

      <footer class="site-footer">
        <div class="page-shell footer-card">
          <div class="footer-grid">
            <section aria-labelledby="help-heading">
